create policy "post-media read auth" on storage.objects for select to authenticated using (bucket_id = 'post-media');
create policy "post-media insert own" on storage.objects for insert to authenticated with check (bucket_id = 'post-media' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "post-media update own" on storage.objects for update to authenticated using (bucket_id = 'post-media' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "post-media delete own" on storage.objects for delete to authenticated using (bucket_id = 'post-media' and (storage.foldername(name))[1] = auth.uid()::text);